style.css:
@-moz-document url-prefix("https://www.goodreads.com/") {
/* Base Colors and Backgrounds */
    body, 
    .gr-mainContent, 
    .siteHeader, 
    .footer,
    .mainContentContainer,
    .dialog,
    .modal__content {
        background-color: #121212 !important;
        color: #e0e0e0 !important;
    }

    .u-defaultType {
        color: #e0e0e0 !important;
    }

    /* Cards and Sections */
    .siteHeader__primaryNavSeparateLine,
    .newsContainer,
    .mainContentFloat,
    .Header__contents,
    .Header__primaryNavContainer,
    .Overlay__window,
    .Overlay__content,
    .Button,
    .TruncatedContent__gradientOverlay,
    .siteAnnouncement,
    .gr-childNewsfeedItem__header,
    .gr-container, 
    .u-backgroundColorWhite, 
    .greyBox, 
    .review, 
    .bookSheet,
    .friendFollow,
    .gr-newsfeedItem,
    .siteHeader__subNav,
    .dropdown__container,
    .responsiveSiteFooter,
    .elementList {
        background-color: #1e1e1e !important;
        background: rgb(0 0 0 / 0.7);
        border-color: #333 !important;
    }

    /* Text Colors */
    h1, h2, h3, h4, .gr-h1, .gr-h2, .gr-h3, .Button__labelItem,
    .bookTitle, .authorName, .userReview {
        color: #ffffff !important;
    }

    a, a:link, .secondaryAction {
        color: #8ab4f8 !important;
    }

    a:hover {
        color: #aecbfa !important;
        text-decoration: underline !important;
    }

    .text--secondary, .greyText, .notes, .readable {
        color: #b0b0b0 !important;
    }

    /* Headers and Navigation */
    .siteHeader__topLine {
        background-color: #181818 !important;
        border-bottom: 1px solid #333 !important;
    }

    .headerPersonalNav__link, .siteHeader__link {
        color: #e0e0e0 !important;
    }

    /* Search Bar */
    .searchBox__input {
        background-color: #2a2a2a !important;
        color: #ffffff !important;
        border: 1px solid #444 !important;
    }

    /* Buttons */
    .gr-button, 
    .wtrButtonContainer button, 
    .button,
    .gr-button--primary {
        background-color: #37474f !important;
        background-image: none !important;
        color: #ffffff !important;
        border: 1px solid #455a64 !important;
    }

    .gr-button:hover {
        background-color: #455a64 !important;
    }

    /* Book Shelves / Tables */
    .gr-table tr:nth-child(even) {
        background-color: #181818 !important;
    }
    
    .gr-table tr:hover {
        background-color: #252525 !important;
    }

    /* Review Boxes and Inputs */
    textarea, input[type="text"] {
        background-color: #2a2a2a !important;
        color: #eeeeee !important;
        border: 1px solid #444 !important;
    }

    /* Borders and Dividers */
    .gr-headerBorder, 
    .borderBottom, 
    .stacked, 
    .section {
        border-color: #333 !important;
    }

    /* Star Ratings */
    .staticStars .p10 { filter: invert(1) brightness(1.5); }
    
    /* Specific Fixes for newer UI (React components) */
    .ResponsiveHeader, .PageBody {
        background-color: #121212 !important;
    }
    
    .Box, .Card {
        background-color: #1e1e1e !important;
        border: 1px solid #333 !important;
    }
    
    /* Invert specific icons if they are too dark */
    .gr-icon--book, .gr-icon--filter {
        filter: invert(0.8);
    }
}
